CREATE DATABASE IF NOT EXISTS campus_activity CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE campus_activity;
CREATE TABLE sys_user (id BIGINT PRIMARY KEY AUTO_INCREMENT, account VARCHAR(50) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, display_name VARCHAR(50) NOT NULL, role ENUM('STUDENT','OWNER','ADMIN') NOT NULL) ENGINE=InnoDB;
CREATE TABLE activity (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, title VARCHAR(100) NOT NULL, category VARCHAR(30) NOT NULL, location VARCHAR(120) NOT NULL, description TEXT, capacity INT NOT NULL, enrolled_count INT NOT NULL DEFAULT 0, status ENUM('DRAFT','PENDING','PUBLISHED','REJECTED') NOT NULL DEFAULT 'DRAFT', signup_deadline DATETIME NOT NULL, start_at DATETIME NOT NULL, end_at DATETIME NOT NULL, FOREIGN KEY (owner_id) REFERENCES sys_user(id), CONSTRAINT ck_capacity CHECK (capacity > 0 AND enrolled_count >= 0 AND enrolled_count <= capacity), INDEX ix_activity_list(status,start_at), INDEX ix_activity_owner(owner_id)) ENGINE=InnoDB;
CREATE TABLE activity_review (id BIGINT PRIMARY KEY AUTO_INCREMENT, activity_id BIGINT NOT NULL, reviewer_id BIGINT NOT NULL, result ENUM('APPROVED','REJECTED') NOT NULL, remark VARCHAR(255), reviewed_at DATETIME NOT NULL, FOREIGN KEY (activity_id) REFERENCES activity(id), FOREIGN KEY (reviewer_id) REFERENCES sys_user(id), INDEX ix_review_history(activity_id,reviewed_at)) ENGINE=InnoDB;
CREATE TABLE registration (id BIGINT PRIMARY KEY AUTO_INCREMENT, activity_id BIGINT NOT NULL, student_id BIGINT NOT NULL, status ENUM('ACTIVE','CANCELLED') NOT NULL, failed_checkins INT NOT NULL DEFAULT 0, registered_at DATETIME NOT NULL, cancelled_at DATETIME, FOREIGN KEY (activity_id) REFERENCES activity(id), FOREIGN KEY (student_id) REFERENCES sys_user(id), UNIQUE KEY uk_registration(activity_id,student_id)) ENGINE=InnoDB;
CREATE TABLE checkin_session (id BIGINT PRIMARY KEY AUTO_INCREMENT, activity_id BIGINT NOT NULL UNIQUE, code_hash VARCHAR(255) NOT NULL, opened_at DATETIME NOT NULL, closes_at DATETIME NOT NULL, closed_at DATETIME, FOREIGN KEY (activity_id) REFERENCES activity(id)) ENGINE=InnoDB;
CREATE TABLE attendance (id BIGINT PRIMARY KEY AUTO_INCREMENT, registration_id BIGINT NOT NULL UNIQUE, signed_at DATETIME NOT NULL, FOREIGN KEY (registration_id) REFERENCES registration(id)) ENGINE=InnoDB;
